-- Marques rangées par ligne commerciale.
--
-- Une marque du catalogue = la ligne telle que le client la nomme : Giorgio Armani, Emporio Armani
-- et Armani Privé sont trois gammes (flacon, prix, nom demandé en boutique) ; de même Dior et
-- La Collection Privée Christian Dior, Tom Ford et Tom Ford Private Blend, etc. Le catalogue les
-- mélangeait sous la marque mère (« Emporio Armani Stronger With You » rangé chez Giorgio Armani,
-- Gris Dior chez Dior). La découpe est celle du référentiel de recherche
-- (`src/lib/search/reference/data/*.json`) : un parfum quitte sa marque mère seulement si le
-- référentiel le range dans une ligne de cette marque.
--
-- Cette migration ne FUSIONNE ni ne SUPPRIME rien :
--   · elle crée la marque de ligne si elle manque (CURATED, PUBLISHED, sans logo : à déposer depuis
--     la gestion), uniquement quand au moins un parfum doit y entrer — jamais de marque vide ;
--   · elle déplace les parfums reconnus et retire du nom le préfixe de ligne collé à la saisie
--     (« Emporio Armani Stronger With You Powerfully » → « Stronger With You Powerfully ») ;
--   · elle laisse intactes les marques mères (slug, logo, statut). Les adresses publiques
--     `/parfums/<marque>/<nom>-<id>` redirigent en 308 : l'identifiant fait foi.
-- Les lignes de vente gardent leur nom de marque d'origine (instantané, jamais réécrit).
-- Rejouée, elle ne trouve plus rien à déplacer. Deux parfums qui arriveraient sous le même nom dans
-- la même ligne : seul le plus ancien bouge, l'autre reste en place (doublon à trancher dans la
-- gestion).

BEGIN;

CREATE TEMP TABLE _deplacements (
  marque_source TEXT NOT NULL,
  parfum_source TEXT NOT NULL,
  marque_cible  TEXT NOT NULL,
  slug_cible    TEXT NOT NULL,
  nom_cible     TEXT NOT NULL
);


-- 1. Lignes manquantes, seulement si un parfum doit y entrer.
SELECT 'c' || substr(md5(random()::text || clock_timestamp()::text || x.marque_cible), 1, 24),
       x.marque_cible, x.slug_cible, 'CURATED', 'PUBLISHED', now()
FROM (
  SELECT DISTINCT d.marque_cible, d.slug_cible
  FROM _deplacements d
  JOIN "Brand"   bs ON lower(btrim(bs.name)) = lower(d.marque_source)
  JOIN "Perfume" p  ON p."brandId" = bs.id AND lower(btrim(p.name)) = lower(d.parfum_source)
) x
WHERE NOT EXISTS (SELECT 1 FROM "Brand" b WHERE lower(btrim(b.name)) = lower(x.marque_cible))
  AND NOT EXISTS (SELECT 1 FROM "Brand" b WHERE b.slug = x.slug_cible);

-- 2. Déplacement. Un parfum ne vise qu'une cible ; une cible (ligne, nom) ne reçoit qu'un parfum ;
--    un nom déjà présent dans la ligne n'est jamais doublé (contrainte unique brandId + name).
WITH candidats AS (
  SELECT DISTINCT ON (p.id) p.id AS perfume_id, bc.id AS cible_id, d.nom_cible
  FROM _deplacements d
  JOIN "Brand"   bs ON lower(btrim(bs.name)) = lower(d.marque_source)
  JOIN "Brand"   bc ON lower(btrim(bc.name)) = lower(d.marque_cible)
  JOIN "Perfume" p  ON p."brandId" = bs.id AND lower(btrim(p.name)) = lower(d.parfum_source)
  WHERE bc.id <> bs.id
  ORDER BY p.id, length(d.parfum_source) DESC
), retenus AS (
  SELECT DISTINCT ON (c.cible_id, lower(c.nom_cible)) c.*
  FROM candidats c
  WHERE NOT EXISTS (
    SELECT 1 FROM "Perfume" q WHERE q."brandId" = c.cible_id AND lower(q.name) = lower(c.nom_cible)
  )
  ORDER BY c.cible_id, lower(c.nom_cible), c.perfume_id
)
UPDATE "Perfume" p
SET "brandId"   = r.cible_id,
    name        = r.nom_cible,
    "updatedAt" = now()
FROM retenus r
WHERE p.id = r.perfume_id;

DROP TABLE _deplacements;

COMMIT;
